p='tmp/issue-dispatch-unit-placement-114.html'
s=open(p).read()
old_edges='''  snap -->|使われる| prj
  snap -->|使われる| diff
  tbl -->|仕様として使われる| t4
  tbl -->|仕様として使われる| fn
  pv -->|参照される| re
  linkStyle 11,13,14,15 stroke:#cf222e,stroke-width:2px,color:#cf222e'''
new_edges='''  prj -->|使われる| snap
  snap -->|使われる| diff
  t4 -->|仕様として使われる| tbl
  fn -->|仕様として使われる| tbl
  re -->|参照される| pv
  linkStyle 11,13,14,15 stroke:#cf222e,stroke-width:2px,color:#cf222e'''
assert s.count(old_edges)==1
s=s.replace(old_edges,new_edges)
# mark the premise pre with flips
i=s.index(new_edges)
j=s.rfind('<pre class="mermaid">',0,i)
s=s[:j]+'<pre class="mermaid" data-flip="prj_snap,t4_tbl,fn_tbl,re_pv">'+s[j+len('<pre class="mermaid">'):]
old_js='''    mermaid.initialize({ startOnLoad: true, flowchart: { useMaxWidth: false } });'''
assert s.count(old_js)==1
new_js='''    mermaid.initialize({ startOnLoad: false, flowchart: { useMaxWidth: false } });
    // data-flip に挙げた矢印 (定義は上から下) の矢じりを、始まりの端 (上) に付け替える。
    // 図の並び (上から作る順) を保ったまま、上向きの「使われる」を描くため。
    mermaid.run().then(function () {
      document.querySelectorAll('pre.mermaid[data-flip]').forEach(function (pre) {
        pre.dataset.flip.split(',').forEach(function (id) {
          pre.querySelectorAll('path[data-id^="L_' + id + '_"]').forEach(function (path) {
            var end = path.getAttribute('marker-end');
            if (!end) { return; }
            path.setAttribute('marker-start', end.replace('pointEnd', 'pointStart'));
            path.removeAttribute('marker-end');
          });
        });
      });
    });'''
s=s.replace(old_js,new_js)
open(p,'w').write(s); print('ok')
